={{ (() => {
  const st = $('🔁 Drop Already Seen').first().json.stats || {};
  const w = $('📊 Sort + Top 10').first().json || {};
  const src = st.sources || {};
  const errs = (st.errors || []).slice(0, 3);
  const lines = [
    '🤖 Job automation finished',
    `Scraped ${st.raw || 0} postings (BA ${src.arbeitsagentur || 0} / LinkedIn ${src.linkedin || 0} / Indeed ${src.indeed || 0})`,
    `Filtered out: internships ${st.droppedStudent || 0} · defence/military ${st.droppedDefense || 0}`,
    `Already in Notion, skipped: ${st.alreadyInNotion || 0}`,
    `New this run: ${st.newJobs || 0} -> scored -> written: ${w.written || '?'}`,
  ];
  if (w.top) lines.push('Top score: ' + w.top);
  if (st.defenseExamples && st.defenseExamples.length) lines.push('Skipped (defence examples): ' + st.defenseExamples.slice(0, 3).join(' | '));
  if (errs.length) lines.push('⚠️ Scrape warnings: ' + errs.join(' | '));
  return lines.join('\n');
})() }}
